<?php
namespace App\Http\Controllers; use App\Models\{TrainingEvaluation,TrainingQuestion,TrainingSession,TrainingTopic}; use App\Services\TrainingEvaluationService; use Illuminate\Http\Request; use Illuminate\Support\Str;
class TrainingEvaluationController extends Controller{public function index(){ $evaluations=TrainingEvaluation::forCompany(auth()->user()->company_id)->with(['session','topic'])->latest()->get();return view('training.evaluations.index',compact('evaluations'));}public function store(Request$r){$d=$r->validate(['training_session_id'=>'required|exists:training_sessions,id','title'=>'required|string|max:255','instructions'=>'required|string|max:3000','evaluation_type'=>'required|in:knowledge_quiz,practical_checklist,instructor_assessment,mixed,external','evaluation_phase'=>'required|in:pre_test,post_test','passing_score'=>'required|numeric|min:0|max:100','maximum_attempts'=>'nullable|integer|min:1|max:10','time_limit_minutes'=>'nullable|integer|min:1','show_result_immediately'=>'required|boolean','show_correct_answers'=>'required|boolean','requires_reinforcement'=>'required|boolean','requires_confirmed_attendance'=>'required|boolean','issues_internal_certificate'=>'required|boolean','opens_at'=>'nullable|date','closes_at'=>'nullable|date|after:opens_at']);$session=TrainingSession::forCompany($r->user()->company_id)->findOrFail($d['training_session_id']);$e=TrainingEvaluation::create(array_merge($d,['company_id'=>$session->company_id,'training_topic_id'=>$session->training_topic_id,'uuid'=>(string)Str::uuid(),'status'=>'draft','created_by'=>$r->user()->id,'updated_by'=>$r->user()->id]));return redirect()->route('training.evaluations.show',$e);}public function show(TrainingEvaluation$evaluation){$this->own($evaluation);$evaluation->load(['session.attendanceEvent.participants','topic','questions.options','attempts.participant']);$bank=TrainingQuestion::forCompany($evaluation->company_id)->where('training_topic_id',$evaluation->training_topic_id)->where('is_active',true)->with('options')->get();return view('training.evaluations.show',compact('evaluation','bank'));}public function publish(TrainingEvaluation$evaluation,Request$r,TrainingEvaluationService$s){$this->own($evaluation);$d=$r->validate(['question_ids'=>'required|array|min:1','question_ids.*'=>'exists:training_questions,id']);$links=$s->publish($evaluation,$d['question_ids'],$r->user()->id);return back()->with(['success'=>'Evaluación publicada y versión congelada.','evaluation_links'=>$links]);}private function own($e){abort_unless((int)$e->company_id===(int)auth()->user()->company_id,403);}}
